#!/usr/bin/env node
// Inlines the vendored OFL font (vendor/fonts/*.woff2) into src/styles/fonts.css as a data URI. Chrome blocks @font-face
// loads from file:// pages, and shared/tools/inline.mjs inlines @import but not url(), so the face travels inside the
// stylesheet. src/styles/main.css imports the generated file.
//   node tools/build-fonts.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const GAME = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(GAME, 'vendor', 'fonts');
const FACES = [
  // the logo, the level signs and the results headings (C4-04)
  // the file is the regular weight; the range stops the browser smearing a fake bold where the page asks for 900
  ['Lilita One', '400 900', 'normal', 'lilita-one-latin-400-normal.woff2'],
];
let css = '/* Generated by tools/build-fonts.mjs from vendor/fonts (SIL Open Font License 1.1). Do not edit. */\n';
for (const [family, weight, style, file] of FACES) {
  const b64 = fs.readFileSync(path.join(SRC, file)).toString('base64');
  css += `@font-face{font-family:"${family}";font-style:${style};font-weight:${weight};font-display:block;` +
    `src:url(data:font/woff2;base64,${b64}) format("woff2")}\n`;
}
fs.writeFileSync(path.join(GAME, 'src', 'styles', 'fonts.css'), css);
console.log('src/styles/fonts.css', (css.length / 1024).toFixed(1), 'KB');
